const input = $input.all();

return input.map(item => {
  const v = item.json;
  return { json: {
    gronerRaw: v,
    gronerSaleId: v.id ?? v.Id ?? null,
    status: v.status ?? v.Status ?? v.statusVenda ?? null,
    saleNumber: v.numero ?? v.Numero ?? null,
    saleDate: v.dataVenda ?? v.DataVenda ?? null,
    customer: {
      name: v.cliente?.nome ?? v.Cliente?.Nome ?? null,
      document: v.cliente?.documento ?? v.Cliente?.Documento ?? null,
      email: v.cliente?.email ?? v.Cliente?.Email ?? null,
      phone: v.cliente?.celular ?? v.Cliente?.Celular ?? null
    },
    total: v.valorTotal ?? v.ValorTotal ?? v.total ?? v.Total ?? null,
    installments: v.parcelas ?? v.Parcelas ?? [],
    items: v.itens ?? v.Itens ?? v.items ?? []
  }};
});

const v = $json;

return [{ json: {
  ...v,
  contaAzulPayload: {
    id_cliente: "TODO-CONTA-AZUL-CLIENTE-ID",
    numero: Number(v.saleNumber || 0),
    situacao: "APROVADO",
    data_venda: v.saleDate ? String(v.saleDate).slice(0, 10) : new Date().toISOString().slice(0, 10),
    observacoes: `Origem: Groner | Venda: ${v.gronerSaleId}`,
    itens: (v.items || []).map((item, index) => ({
      descricao: item.descricao ?? item.nome ?? `Item ${index + 1}`,
      quantidade: Number(item.quantidade ?? item.qtd ?? 1),
      valor: Number(item.valor ?? item.valorUnitario ?? 0),
      id: "TODO-CONTA-AZUL-PRODUTO-ID"
    }))
  }
}}];
